/**
 * Single-statement transactions where, after every {@code awaitEvery} commits, the caller waits until the direct
 * adjacency index has applied every committed delta (an exact view of the current data revision). Throughput is
 * transactions per second including the amortised wait; {@code waitTimeouts} counts waits that did not finish within 60
 * seconds.
 */
@State(Scope.Benchmark)
@Warmup(iterations = 2, time = 3)
@Measurement(iterations = 4, time = 5)
@BenchmarkMode({ Mode.Throughput })
@Fork(value = 1, jvmArgs = { "-Xms4G", "-Xmx4G", "-XX:+UseG1GC" })
@OutputTimeUnit(TimeUnit.SECONDS)
public class TxnAdjacencyCatchUpBenchmark {

	@Param({ "1", "10", "100", "1000", "10000" })
	public int awaitEvery;

	@Param({ "NONE", "READ_COMMITTED" })
	public IsolationLevels isolation;

	private File file;
	private LmdbStore store;
	private SailRepository repository;
	private SailRepositoryConnection connection;
	private RandomLiteralGenerator literalGenerator;
	private Random random;
	private List<IRI> resources;
	private List<IRI> predicates;
	private int sinceWait;
	private long waitTimeouts;
	private long waits;

	@Setup(Level.Iteration)
	public void setUp() throws InterruptedException {
		file = Files.newTemporaryFolder();
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setSketchEstimatorEnabled(false);
		config.setForceSync(false);
		config.setTripleDBSize(4L * 1024 * 1024 * 1024);
		config.setValueDBSize(4L * 1024 * 1024 * 1024);
		config.setDirectAdjacencyEnabled(true);
		config.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		store = new LmdbStore(file, config);
		repository = new SailRepository(store);
		connection = repository.getConnection();
		random = new Random(1337);
		literalGenerator = new RandomLiteralGenerator(connection.getValueFactory(), random);
		resources = new ArrayList<>();
		predicates = new ArrayList<>();
		for (int i = 0; i < 1000; i++) {
			resources.add(connection.getValueFactory().createIRI("some:resource-" + i));
		}
		for (int i = 0; i < 20; i++) {
			predicates.add(connection.getValueFactory().createIRI("some:predicate-" + i));
		}
		// seed one statement so the startup build has something to serve, then wait for the index to be ready
		connection.begin(isolation);
		connection.add(resources.get(0), predicates.get(0), literalGenerator.createRandomLiteral());
		connection.commit();
		if (!store.awaitDirectAdjacencyReady(120, TimeUnit.SECONDS)) {
			throw new IllegalStateException("direct adjacency did not become ready: "
					+ store.getDirectAdjacencyReadinessDescription());
		}
		sinceWait = 0;
		waitTimeouts = 0;
		waits = 0;
		System.gc();
	}

	@TearDown(Level.Iteration)
	public void tearDown() {
		System.out.println("[catch-up] awaitEvery=" + awaitEvery + " isolation=" + isolation + " waits=" + waits
				+ " waitTimeouts=" + waitTimeouts + " readiness=" + store.getDirectAdjacencyReadinessDescription());
		if (connection != null) {
			connection.close();
			connection = null;
		}
		try {
			repository.shutDown();
		} finally {
			LmdbTestUtil.deleteDir(file);
		}
	}

	@Benchmark
	public void commitThenAwaitApplied() throws InterruptedException {
		connection.begin(isolation);
		connection.add(resources.get(random.nextInt(resources.size())),
				predicates.get(random.nextInt(predicates.size())), literalGenerator.createRandomLiteral());
		connection.commit();
		if (++sinceWait >= awaitEvery) {
			sinceWait = 0;
			waits++;
			if (!store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)) {
				waitTimeouts++;
			}
		}
	}
}
